// The first width at which Breakdown appears with costUsage, measured column by
// column from 50 to 230: Model 94, Breakdown 106, In 114, Cache read 126,
// Est. cost 138, Cache write 151. Before the column, In was 102, Cache read 114,
// Est. cost 126 and Cache write 139.
func TestBreakdownLayoutAtEachWidth(t *testing.T) {
	tests := []struct {
		width int
		want  []string
	}{
		{230, []string{"Agent", "ID", "Est. cost", "State", "Tools", "Duration", "Model", breakdownTitle, "In", "Out", "Cache read", "Cache write", "Total", "Share"}},
		{151, []string{"Agent", "ID", "Est. cost", "State", "Tools", "Duration", "Model", breakdownTitle, "In", "Out", "Cache read", "Cache write", "Total", "Share"}},
		{150, []string{"Agent", "ID", "Est. cost", "State", "Tools", "Duration", "Model", breakdownTitle, "In", "Out", "Cache read", "Total", "Share"}},
		{138, []string{"Agent", "ID", "Est. cost", "State", "Tools", "Duration", "Model", breakdownTitle, "In", "Out", "Cache read", "Total", "Share"}},
		{137, []string{"Agent", "ID", "State", "Tools", "Duration", "Model", breakdownTitle, "In", "Out", "Cache read", "Total", "Share"}},
		{126, []string{"Agent", "ID", "State", "Tools", "Duration", "Model", breakdownTitle, "In", "Out", "Cache read", "Total", "Share"}},
		{125, []string{"Agent", "ID", "State", "Tools", "Duration", "Model", breakdownTitle, "In", "Out", "Total", "Share"}},
		{114, []string{"Agent", "ID", "State", "Tools", "Duration", "Model", breakdownTitle, "In", "Out", "Total", "Share"}},
		{113, []string{"Agent", "ID", "State", "Tools", "Duration", "Model", breakdownTitle, "Out", "Total", "Share"}}, // In goes before Breakdown
		{106, []string{"Agent", "ID", "State", "Tools", "Duration", "Model", breakdownTitle, "Out", "Total", "Share"}}, // narrowest with the bar
		{105, []string{"Agent", "ID", "State", "Tools", "Duration", "Model", "Out", "Total", "Share"}},                 // Breakdown goes before Model
		{100, []string{"Agent", "ID", "State", "Tools", "Duration", "Model", "Out", "Total", "Share"}},                 // unchanged
		{80, []string{"Agent", "ID", "State", "Tools", "Duration", "Out", "Total", "Share"}},                           // unchanged
		{60, []string{"Agent", "ID", "Out", "Total", "Share"}},                                                         // unchanged
	}
	for _, tt := range tests {
		t.Run(strconv.Itoa(tt.width), func(t *testing.T) {
			m := atPricedAgents(t, nil, tt.width, costUsage())
			if got := m.agentTable.RenderedWidth(); got != tt.width-2 {
				t.Errorf("rendered width = %d, want %d (Rule 116)", got, tt.width-2)
			}
			got := shownTitles(t, m.View())
			if strings.Join(got, ",") != strings.Join(tt.want, ",") {
				t.Errorf("columns at %d = %v, want %v:\n%s", tt.width, got, tt.want, m.View())
			}
		})
	}
}

// Rule 116 at every width from 50 to 230, the bar column coming and going, and
// the order in which optional columns give way holds at each of them.
func TestBreakdownRule116AndDropOrderAtEveryWidth(t *testing.T) {
	// Optional columns in the order they disappear: Cache write, Est. cost, Cache read, In, Breakdown, Model, Duration, Tools, State.
	vanish := []string{"Cache write", "Est. cost", "Cache read", "In", breakdownTitle, "Model", "Duration", "Tools", "State"}
	shown, widths := 0, 0
	for w := 50; w <= 230; w++ {
		m := atPricedAgents(t, nil, w, costUsage())
		widths++
		if got := m.agentTable.RenderedWidth(); got != w-2 {
			t.Fatalf("width %d: rendered width = %d, want %d (Rule 116)", w, got, w-2)
		}
		cols := shownTitles(t, m.View())
		if i := slices.Index(cols, breakdownTitle); i >= 0 {
			shown++
			if cols[i-1] != "Model" || cols[i+1] != "In" && cols[i+1] != "Out" {
				t.Fatalf("width %d: %s sits between %q and %q: %v", w, breakdownTitle, cols[i-1], cols[i+1], cols)
			}
		}
		// A column that is gone means every column that goes before it is gone.
		for i, gone := range vanish {
			if slices.Contains(cols, gone) {
				continue
			}
			for _, kept := range vanish[:i] {
				if slices.Contains(cols, kept) {
					t.Fatalf("width %d: %s is gone but %s, which goes first, is still shown: %v", w, gone, kept, cols)
				}
			}
		}
	}
	if widths != 181 {
		t.Fatalf("checked %d widths, want 181 (50..230)", widths)
	}
	if shown == 0 {
		t.Fatal("Breakdown never appears between 50 and 230 columns")
	}
	if shown == widths {
		t.Fatal("Breakdown appears at every width: it never gives way")
	}
}

// The bar is ten cells wide on screen: one orchestrator line carries exactly ten
// gauge glyphs, whatever the width it is shown at.
func TestBreakdownBarIsTenCellsOnScreen(t *testing.T) {
	for _, w := range []int{106, 150, 230} {
		m := atPricedAgents(t, nil, w, costUsage())
		var line string
		for _, l := range strings.Split(stripANSI(m.View()), "\n") {
			if strings.Contains(l, orchestratorLabel) {
				line = l
			}
		}
		if line == "" {
			t.Fatalf("width %d: no orchestrator line:\n%s", w, m.View())
		}
		if got := strings.Count(line, "░"); got != 10 {
			t.Errorf("width %d: %d gauge glyphs on the orchestrator line, want 10: %q", w, got, line)
		}
	}
}

// AC5: a session without a single token has a dash for every bar, a dash for
// every Share, and does not panic.
func TestBreakdownZeroTokenSession(t *testing.T) {
	u := agentusage.Usage{Agents: []agentusage.Agent{{Main: true}, {ID: "a01", Type: "coder"}, {ID: "a02", Type: "tester"}}}
	m := atPricedAgents(t, nil, 200, u)
	if !slices.Contains(shownTitles(t, m.View()), breakdownTitle) {
		t.Fatalf("Breakdown is not shown at 200 columns:\n%s", m.View())
	}
	c := column(t, breakdownTitle)
	rows := m.agentTable.Items()
	if len(rows) != 3 {
		t.Fatalf("got %d rows, want 3", len(rows))
	}
	for _, r := range rows {
		if got := c.Cell(r); got != noValue {
			t.Errorf("%s: bar cell = %q, want %q", roleCell(r), got, noValue)
		}
		if got := shareCell(r); got != noValue {
			t.Errorf("%s: Share = %q, want %q", roleCell(r), got, noValue)
		}
	}
	if strings.Contains(stripANSI(m.View()), "░") {
		t.Errorf("a gauge glyph is drawn for an agent with no token:\n%s", m.View())
	}
}

// AC6: the mix follows a live session. A read that adds cache read to one agent
// changes its spans and only its spans.
func TestBreakdownFollowsALiveUpdate(t *testing.T) {
	before := agentusage.Usage{Agents: []agentusage.Agent{
		{Main: true, Tokens: agentusage.Tokens{Input: 500, Output: 500}},
		{ID: "a01", Type: "coder", Tokens: agentusage.Tokens{Input: 500, Output: 500}},
	}}
	after := agentusage.Usage{Agents: []agentusage.Agent{
		before.Agents[0],
		{ID: "a01", Type: "coder", Tokens: agentusage.Tokens{Input: 500, Output: 500, CacheRead: 1000}},
	}}
	m := atPricedAgents(t, nil, 200, before)
	c := column(t, breakdownTitle)
	widths := func(m Model) map[string][]int {
		out := map[string][]int{}
		for _, r := range m.agentTable.Items() {
			for _, s := range c.Spans(r) {
				out[roleCell(r)] = append(out[roleCell(r)], s.Width)
			}
		}
		return out
	}
	was := widths(m)
	if len(was) != 2 {
		t.Fatalf("precondition: want spans for both agents, got %v", was)
	}
	m = answer(t, m, after)
	now := widths(m)
	if slices.Equal(now["coder"], was["coder"]) {
		t.Errorf("coder spans did not change after cache read was added: %v", now["coder"])
	}
	if want, _ := segmentCells(after.Agents[1].Tokens); !slices.Equal(now["coder"], want[:]) {
		t.Errorf("coder spans = %v, want %v", now["coder"], want)
	}
	if !slices.Equal(now["orchestrator"], was["orchestrator"]) {
		t.Errorf("orchestrator spans changed from %v to %v", was["orchestrator"], now["orchestrator"])
	}
}

